<?php

declare(strict_types=1);
namespace OCA\ERP\Db;
use OCP\AppFramework\Db\Entity;
/** @method int getMeasurementRecordId() @method void setMeasurementRecordId(int $id) @method string getUuid() @method void setUuid(string $uuid) @method string getBlockType() @method void setBlockType(string $type) @method string getPayload() @method void setPayload(string $payload) @method int getPosition() @method void setPosition(int $position) @method int getVersion() @method void setVersion(int $version) @method int getCreatedAt() @method void setCreatedAt(int $createdAt) @method int getUpdatedAt() @method void setUpdatedAt(int $updatedAt) @method int|null getDeletedAt() @method void setDeletedAt(?int $deletedAt) */
class MeasurementBlock extends Entity implements \JsonSerializable { protected int $measurementRecordId=0; protected string $uuid=''; protected string $blockType=''; protected string $payload='{}'; protected int $position=0; protected int $version=1; protected int $createdAt=0; protected int $updatedAt=0; protected ?int $deletedAt=null; public function __construct(){foreach(['id','measurementRecordId','position','version','createdAt','updatedAt','deletedAt'] as $f)$this->addType($f,'integer');} public function jsonSerialize():array{return ['id'=>$this->getId(),'uuid'=>$this->getUuid(),'measurementRecordId'=>$this->getMeasurementRecordId(),'type'=>$this->getBlockType(),'payload'=>json_decode($this->getPayload(),true,512,JSON_THROW_ON_ERROR),'position'=>$this->getPosition(),'version'=>$this->getVersion(),'createdAt'=>$this->getCreatedAt(),'updatedAt'=>$this->getUpdatedAt(),'deletedAt'=>$this->getDeletedAt()];}}
